        typ="InvalidInput"
    elif "Inconsistency in user input" in err:
        typ="Inconsistency"
    elif "Fatal error" in err:
        typ="Fatal"
    elif "Feature not implemented" in err:
        typ="NotImplemented"
    elif "System I/O error" in err:
        typ="SystemIO"
    elif "Invalid command-line options" in err:
        typ="InvalidOptions"
    elif p.returncode==0 and len(out)==0:
        typ="SuccessEmpty"
    elif p.returncode==0:
        typ=f"SuccessOut{len(out)}"
    else:
