def run_orig(args):
    p=subprocess.run(["/tmp/origdir/executable"]+args,capture_output=True,cwd="/tmp")
    return p.stdout,p.stderr,p.returncode
def norm(b):
    s=b.decode(errors='ignore')
    # Normalize exe paths (both resolve to /workspace/...? New symlink /tmp/newdir/executable -> /workspace/executable (new, regular file), resolves to /workspace/executable. Orig symlink /tmp/origdir/executable -> /workspace/executable.orig, resolves to /workspace/executable.orig. Good. Replace both with <EXE>.
    s=s.replace("/workspace/executable.orig","<EXE>").replace("/workspace/executable","<EXE>")
